参考代码见解析：

```cpp
#include <bits/stdc++.h>
using namespace std;
string a[1000], b[1000];
int main() {
    int n;
    cin >> n;
    for(int i=0; i<n; i++) {
        cin >> a[i];
        b[i] = a[i];  //保存旋转后的矩阵
    }
    //顺时针旋转 90°：a[i][j]=>b[j][n-1-i]
    for(int i=0; i<n; i++) {
        for(int j=0; j<n; j++) {
            b[j][n-1-i] = a[i][j];
        }
    }
    for(int i=0; i<n; i++) {
        cout << b[i] << endl;
    }
    return 0;
}
```

参考代码见解析：

```cpp
#include <bits/stdc++.h>
using namespace std;
int h[100];
int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> h[i];
    }
    //若后面高于前面的， 需要增加高度差的次数
    //若后面低于前面， 不需要增加次数
    int ans = h[0];
    for (int i = 1; i < n; i++) {
        int d = h[i] - h[i - 1];
        if(d > 0)
            ans += d;
    }
    cout << ans << endl;
    return 0;
}
```
